import{_ as o,o as e,c as n,R as r}from"./chunks/framework.CGdQ6rU-.js";const c=JSON.parse('{"title":"3. 卷首语","description":"","frontmatter":{"title":"3. 卷首语","tags":["2025 中国开源年度报告"]},"headers":[],"relativePath":"preface.md","filePath":"preface.md","lastUpdated":1783589798000}'),s={name:"preface.md"};function p(a,t,u,g,i,q){return e(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="卷首语" tabindex="-1">卷首语 <a class="header-anchor" href="#卷首语" aria-label="Permalink to &quot;卷首语&quot;">​</a></h1><p>去年此时，我在卷首语中写道：2024 年，开源 AI 的井喷式爆发彻底改写了行业规则。彼时我们满怀期待，却未曾预料到，<strong>2025 年交出的答卷远超想象——这一年，开源不仅改写了规则，更开始重新定义规则本身</strong>。</p><p>年初，DeepSeek 以纯强化学习训练的开源模型打破了闭源巨头的技术垄断，实现了&quot;模型平权&quot;。这一突破迅速引发连锁反应：Qwen、GLM、Kimi 等国产开源模型密集涌现，中国开源模型在 Hugging Face 的下载量首次超越美国。与此同时，在软件领域，OpenHarmony 以超过 6 万的 OpenRank 值登顶全球开源项目影响力之巅，openEuler 紧随其后。<strong>当我们谈论&quot;中国开源力量&quot;时，它已不再是一种愿景，而是一组可被验证的数据。</strong></p><p>然而，2025 年留给我们最深刻的命题，或许不是哪个模型又刷新了榜单，而是一个更根本的追问：<strong>当 AI 开始写代码，开源协作的底层逻辑会发生什么变化？</strong></p><p>这一年被业界称为&quot;智能体元年&quot;。GitHub Copilot 从代码补全进化为自主编程代理，Cursor 凭借产品主导增长（PLG）模式年内 ARR 突破 10 亿美元，Roo-Code、Cline、Aider、OpenHands 等 AI Coding 智能体密集涌现，占据了全球新势力开源项目榜单的半壁江山。&quot;Vibe Coding&quot;从一个梗变成了一种真实的开发方式——开发者用自然语言描述意图，由 AI 生成代码、调试、甚至提交 PR。软件开发的门槛从未如此之低，产出效率从未如此之高。</p><p>但硬币的另一面已在数据中显现。本份报告的数据篇揭示了一个值得警惕的信号：2025 年全球开源生态的 OpenRank 贡献度与影响力出现了同步下滑，其中贡献度降幅更为显著。报告分析指出，&quot;随着生成式 AI 工具的广泛应用，部分原本依赖社区协作完成的任务被技术手段替代，在提升个体开发效率的同时，客观上降低了开发者之间的互动需求与协作频率。&quot;换言之，<strong>AI 让个体变强了，但协作网络变稀疏了</strong>。当一个开发者借助 AI 就能独立完成过去需要三五人协作的任务时，Issue 讨论减少了，PR Review 变轻了，社区中那些看似低效却至关重要的知识传递与信任构建，正在被悄然侵蚀。</p><p>这不是危言耸听。开源的本质从来不只是&quot;代码的公开&quot;，而是&quot;协作的发生&quot;。如果 AI Coding 的终局是每个人都成为全栈独行侠，那么开源社区赖以存续的协作文化、代码审查机制、导师制度和知识沉淀，都将面临根本性的重构。我们尚不知道答案，但我认为，<strong>这恰恰是开源社区最应该直面的时代命题——不是抵抗 AI，而是思考如何在 AI 原生的时代重新设计协作</strong>。</p><p>本份报告在结构上也有重要拓展。<strong>数据篇</strong>首次引入 OSDGs（开源发展目标）框架，揭示了中美开源生态的结构性差异：美国项目高度全球化，本土贡献仅占 38%；而中国项目仍以本土贡献为主，占比高达 79%。<strong>一个真正领先的开源生态，不仅要向世界输出代码，更要让世界愿意走进来共建。</strong> <strong>Web3.0 篇</strong>首次独立成章，剖析了中文开发者在去中心化开源协议中&quot;代码在场、声音缺席&quot;的现状。<strong>开源具身智能篇</strong>亦是今年新设的独立篇章——如果说 DeepSeek 让中国开源在数字世界实现了&quot;模型平权&quot;，那么这一年以 VLA 模型、世界模型与开源本体为代表的具身浪潮，正推动开源力量<strong>从&quot;数字世界&quot;走向&quot;物理世界&quot;</strong>，去重新定义机器理解世界、并在其中行动的方式。<strong>开源大事记</strong>以九大章节全景呈现了这一年的重大事件——从国务院将开源纳入&quot;AI+&quot;专项行动，到联合国举办第二届开源周，开源正从技术社区的内部语言，演变为政策制定者和国际组织的共同词汇。</p><p>站在 2026 年回望，2025 年像是一道分水岭：一边是中国开源力量的历史性崛起，一边是 AI 对开源协作范式的深层冲击。繁荣与变革并存，确定性与不确定性交织。但我始终相信，<strong>开源社区最擅长的事情，就是把不确定性变成协作的起点</strong>。</p><p>感谢所有参与本份报告编纂的志愿者，感谢每一位以行动定义中国开源的同行者。</p><p>—— 江波，开源社 2025 年度理事长</p>',11)])])}const l=o(s,[["render",p]]);export{c as __pageData,l as default};
